WITH by_dimension AS (SELECT dim.country, e.event_type, COUNT(*) AS num_rows, MAX(e.duration_sec) AS max_duration_sec, GROUPING_ID() AS level_id FROM web_events e INNER JOIN sessions dim ON e.session_id = dim.id GROUP BY GROUPING SETS ((dim.country, e.event_type), (dim.country), ())) SELECT country, event_type, num_rows, max_duration_sec, level_id, CASE WHEN country RLIKE '^(TH|US)$' THEN 'PRIORITY' ELSE 'GROUP_A' END AS country_zone FROM by_dimension ORDER BY max_duration_sec
